/* Use a geometric icon rather than a font glyph for every dismiss control. */
(()=>{'use strict';const icon='<svg viewBox="0 0 24 24" aria-hidden="true" focusable="false"><path d="m6 6 12 12M18 6 6 18"/></svg>';function sync(){document.querySelectorAll('button').forEach(b=>{if(b.classList.contains('centered-dismiss'))return;if(!/^[×✕✖]$/.test(b.textContent.trim()))return;b.classList.add('centered-dismiss');if(getComputedStyle(b).position==='static')b.style.position='relative';if(!b.getAttribute('aria-label'))b.setAttribute('aria-label','بستن');b.innerHTML=icon})}let queued=false;new MutationObserver(()=>{if(queued)return;queued=true;queueMicrotask(()=>{queued=false;sync()})}).observe(document.body,{subtree:true,childList:true});sync()})();
